\"\"\"

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Mapping


DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
_RESPONSES_PATH = \"/responses\"


class OpenAIError(Exception):
    \"\"\"Raised when the Responses API request fails or returns no text.\"\"\"

    def __init__(self, message: str, *, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


class _RejectRedirects(urllib.request.HTTPRedirectHandler):
    \"\"\"Refuse redirects so the bearer token is not sent to another host.\"\"\"

    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        raise OpenAIError(f\"Refusing redirect from the Responses API (HTTP {code}).\")


def _require_text(value: str, name: str) -> str:
    if not isinstance(value, str):
        raise TypeError(f\"{name} must be a string.\")
    if not value.strip():
        raise ValueError(f\"{name} must not be empty.\")
    return value


def _api_key(explicit: str | None) -> str:
    key = explicit if explicit is not None else os.environ.get(\"OPENAI_API_KEY\", \"\")
    if not isinstance(key, str) or not key.strip():
        raise OpenAIError(\"Set OPENAI_API_KEY or pass api_key.\")
    return key


def _model(explicit: str | None) -> str:
    model = explicit if explicit is not None else os.environ.get(\"OPENAI_MODEL\", \"\")
    return _require_text(model, \"model\")


def _base_url(explicit: str | None) -> str:
    base = explicit if explicit is not None else os.environ.get(\"OPENAI_BASE_URL\", DEFAULT_BASE_URL)
    if not isinstance(base, str) or not base.strip():
        raise OpenAIError(\"OPENAI_BASE_URL is empty.\")
    return base.rstrip(\"/\")


def output_text(response: Mapping[str, Any]) -> str:
    \"\"\"Return assistant text from a Responses API JSON object.\"\"\"
    status = response.get(\"status\")
    if status not in (None, \"completed\"):
        detail = response.get(\"error\") or response.get(\"incomplete_details\") or status
        raise OpenAIError(f\"Responses API did not complete successfully ({detail}).\")

    chunks: list[str] = []
    for item in response.get(\"output\") or []:
        if not isinstance(item, Mapping) or item.get(\"type\") "'!= "message":
            continue
        for part in item.get("content") or []:
            if not isinstance(part, Mapping):
                continue
            part_type = part.get("type")
            if part_type == "output_text":
                text = part.get("text")
                if isinstance(text, str):
                    chunks.append(text)
            elif part_type == "refusal":
                refusal = part.get("refusal")
                message = refusal if isinstance(refusal, str) and refusal else "The model refused the prompt."
                raise OpenAIError(message)
    if not chunks:
        raise OpenAIError("Responses API returned no output text.")
    return "".join(chunks)


class OpenAIClient:
    """Minimal client for private text calls to POST /v1/responses."""

    def __init__(
        self,
        api_key: str | None = None,
        *,
        base_url: str | None = None,
        model: str | None = None,
        timeout: float = 60.0,
        organization: str | None = None,
        project: str | None = None,
    ) -> None:
        self.api_key = [REDACTED_SECRET]
        self.base_url = _base_url(base_url)
        self.model = model
        self.timeout = timeout
        self.organization = organization if organization is not None else os.environ.get("OPENAI_ORGANIZATION")
        self.project = project if project is not None else os.environ.get("OPENAI_PROJECT")
        self._opener = urllib.request.build_opener(_RejectRedirects)

    def send_text(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
        store: bool = False,
        timeout: float | None = None,
    ) -> str:
        """Send one private text prompt and return the assistant text.

        ``store`` defaults to false so the response is not kept for later
        retrieval. Account-level data retention is controlled by OpenAI, not
        by this module.
        """
        return output_text(
            self.create_response(
                prompt,
                model=model,
                instructions=instructions,
                max_output_tokens=max_output_tokens,
                temperature=temperature,
                store=store,
                timeout=timeout,
            )
        )

    def create_response(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
        store: bool = False,
        timeout: float | None = None,
    ) -> dict[str, Any]:
        """POST a text prompt to the Responses API and return parsed JSON."""
        text = _require_text(prompt, "prompt")
        payload: dict[str, Any] = {
            "model": _model(model if model is not None else self.model),
            "input": text,
            "store": bool(store),
        }
        if instructions is not None:
            payload["instructions"] = _require_text(instructions, "instructions")
        if max_output_tokens is not None:
            if not isinstance(max_output_tokens, int) or max_output_tokens < 1:
                raise ValueError("max_output_tokens must be a positive integer.")
            payload["max_output_tokens"] = max_output_tokens
        if temperature is not None:
            if isinstance(temperature, bool) or not isinstance(temperature, (int, float)):
                raise TypeError("temperature must be a number.")
            payload["temperature"] = temperature

        url = self.base_url + _RESPONSES_PATH
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project

        request = urllib.request.Request(url, data=body, headers=headers, method="POST")
        try:
            with self._opener.open(request, timeout=self.timeout if timeout is None else timeout) as response:
                raw = response.read()
        except urllib.error.HTTPError as exc:
            detail = _safe_error_detail(exc)
            raise OpenAIError(
                f"Responses API request failed (HTTP {exc.code}): {detail}",
                status=exc.code,
            ) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(f"Could not reach the Responses API: {exc.reason}") from None

        try:
            parsed = json.loads(raw.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise OpenAIError("Responses API returned invalid JSON.") from None
        if not isinstance(parsed, dict):
            raise OpenAIError("Responses API returned an unexpected payload.")
        return parsed


def send_private_prompt(prompt: str, **kwargs: Any) -> str:
    """Send ``prompt`` with a new client. See ``OpenAIClient.send_text``."""
    client_keys = ("api_key", "base_url", "timeout", "organization", "project")
    client_kwargs = {key: kwargs.pop(key) for key in client_keys if key in kwargs}
    if "model" in kwargs and "model" not in client_kwargs:
        pass
    return OpenAIClient(**client_kwargs).send_text(prompt, **kwargs)


def _safe_error_detail(exc: urllib.error.HTTPError) -> str:
    try:
        raw = exc.read()
    except Exception:
        return "no error body"
    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError):
        return "unreadable error body"
    error = parsed.get("error") if isinstance(parsed, dict) else None
    if isinstance(error, dict):
        message = error.get("message")
        if isinstance(message, str) and message.strip():
            return message.strip()
    return "request rejected"
