import io
import json
import urllib.error
from unittest.mock import patch
import openai_client as oc

sample = {
    \"status\": \"completed\",
    \"output\": [
        {\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"hello private\"}]}
    ],
}

class FakeResp(io.BytesIO):
    def __enter__(self):
        return self
    def __exit__(self, *args):
        return False

def fake_open(request, timeout=None):
    body = json.loads(request.data.decode())
    assert body[\"input\"] == \"secret prompt\"
    assert body[\"store\"] is False
    assert body[\"model\"] == \"gpt-test\"
    assert request.get_method() == \"POST\"
    assert request.full_url == \"https://api.openai.com/v1/responses\"
    assert request.get_header(\"Authorization\") == \"Bearer test-key\"
    assert timeout == 60.0
    return FakeResp(json.dumps(sample).encode())

client = oc.OpenAIClient(api_key=\"test-key\", model=\"gpt-test\")
with patch.object(client._opener, \"open\", fake_open):
    text = client.send_text(\"secret prompt\")
