        client.send_text(\"secret prompt\")
    except oc.OpenAIError as exc:
        msg = str(exc)
        assert \"secret prompt\" not in msg
        assert \"test-key\" not in msg
        assert \"bad key\" in msg
        assert exc.status == 401
    else:
        raise SystemExit(\"expected http error\")

